import { signal } from '@angular/core';
import { ComponentFixture, TestBed } from '@angular/core/testing';
import { CpThemeService } from '@creator-pantry/ui';

import { LandingTourCapture, TOUR_CAPTURES } from './landing-tour.captures';
import { CAPTURED_TOUR_PANELS, LandingTourComponent, TOUR_STOPS } from './landing-tour.component';
import { COMING_TO_EVERY_ACCOUNT, DEFAULT_VALUE_PROPS } from './landing-value-props.component';

/**
 * The tour shows the panels `landing-tour.captures.ts` lists, and that file is generated by
 * `npm run capture:tour` — empty until someone runs it. So these specs supply their own captures, and one of
 * them covers the other case: with none, there is no tour on the page at all.
 */
describe('LandingTourComponent', () => {
  let fixture: ComponentFixture<LandingTourComponent>;
  let host: HTMLElement;
  let resolvedTheme: ReturnType<typeof signal<'light' | 'dark'>>;

  const captures = (...panels: string[]): LandingTourCapture[] =>
    panels.map((panel) => ({ panel, width: 640, height: 400, capturedOn: '2026-10-24' }) as LandingTourCapture);

  const everyPanel = captures(...TOUR_STOPS.map((stop) => stop.panel));

  async function create(supplied: LandingTourCapture[]): Promise<void> {
    resolvedTheme = signal<'light' | 'dark'>('light');
    await TestBed.configureTestingModule({
      imports: [LandingTourComponent],
      providers: [{ provide: CpThemeService, useValue: { resolved: resolvedTheme } }],
    }).compileComponents();
    fixture = TestBed.createComponent(LandingTourComponent);
    fixture.componentRef.setInput('captures', supplied);
    host = fixture.nativeElement;
    fixture.detectChanges();
    await fixture.whenStable();
  }

  const tabs = () => Array.from(host.querySelectorAll<HTMLButtonElement>('[role="tab"]'));
  const tabFor = (panel: string) => host.querySelector<HTMLButtonElement>(`#tab-${panel}`)!;

  /**
   * The tour reads the real address, so a spec that is about a link sets one and puts it back. `replaceState`
   * keeps the karma page where it was; changing `location.hash` outright would scroll the runner.
   */
  async function arriveAt(panel: string): Promise<void> {
    const before = location.href;
    history.replaceState(history.state, '', `#tour-${panel}`);
    window.dispatchEvent(new HashChangeEvent('hashchange'));
    fixture.detectChanges();
    await fixture.whenStable();
    history.replaceState(history.state, '', before);
  }
  const selectedTab = () => tabs().find((tab) => tab.getAttribute('aria-selected') === 'true')!;
  const shown = () => Array.from(host.querySelectorAll('.shot.current img')).map((img) => img.getAttribute('src'));

  afterEach(() => {
    fixture?.destroy();
    // The address is shared with every other spec in the run, and the tour reads it on creation.
    history.replaceState(history.state, '', location.pathname + location.search);
  });

  it('renders nothing while no panel has been captured', async () => {
    await create([]);

    expect(host.querySelector('section')).toBeNull();
  });

  it('names as its panels exactly the stops the generated captures cover', () => {
    const generated = TOUR_STOPS.filter((stop) => TOUR_CAPTURES.some((capture) => capture.panel === stop.panel));

    expect(CAPTURED_TOUR_PANELS).toEqual(generated.map((stop) => stop.panel));
  });

  it('shows a tab per captured panel, in the tour’s order, and nothing for an uncaptured one', async () => {
    await create(captures('image-studio', 'publishing'));

    expect(tabs().map((tab) => tab.textContent?.trim())).toEqual(['Image Studio', 'Publishing']);
  });

  it('gives each panel its promise, three benefits and an anchor to link to', async () => {
    await create(everyPanel);

    TOUR_STOPS.forEach((stop) => {
      const panel = host.querySelector<HTMLElement>(`#panel-${stop.panel}`)!;
      expect(panel.getAttribute('aria-labelledby')).toBe(`tab-${stop.panel}`);
      expect(host.querySelector(`#tour-${stop.panel}`)).not.toBeNull();
    });
    expect(selectedTab().textContent?.trim()).toBe(TOUR_STOPS[0].label);
    const first = host.querySelector<HTMLElement>(`#panel-${TOUR_STOPS[0].panel}`)!;
    expect(first.querySelector('.promise')?.textContent?.trim()).toBe(TOUR_STOPS[0].promise);
    expect(first.querySelectorAll('li').length).toBe(3);
  });

  it('moves between tabs with the arrow keys and shows that panel’s picture', async () => {
    await create(everyPanel);
    const tablist = host.querySelector('[role="tablist"]')!;

    tablist.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowRight', bubbles: true }));
    fixture.detectChanges();
    await fixture.whenStable();

    expect(selectedTab().textContent?.trim()).toBe(TOUR_STOPS[1].label);
    expect(shown()).toEqual([`/images/tour/${TOUR_STOPS[1].panel}-light@1x.webp`]);
  });

  it('keeps a picture once shown, so one fades into the next rather than appearing from nothing', async () => {
    await create(everyPanel);
    const tablist = host.querySelector('[role="tablist"]')!;

    tablist.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowRight', bubbles: true }));
    fixture.detectChanges();
    await fixture.whenStable();

    expect(host.querySelectorAll('.shot').length).toBe(2);
    expect(shown().length).toBe(1);
  });

  it('loads only the first panel’s picture until another tab is asked for', async () => {
    await create(everyPanel);

    expect(host.querySelectorAll('.shot').length).toBe(1);
  });

  it('offers AVIF before WebP, at both densities, and reserves the picture’s size', async () => {
    await create(captures('image-studio'));
    const sources = Array.from(host.querySelectorAll('.shot source'));
    const img = host.querySelector<HTMLImageElement>('.shot img')!;

    expect(sources.map((source) => source.getAttribute('type'))).toEqual(['image/avif', 'image/webp']);
    expect(sources[0].getAttribute('srcset')).toBe('/images/tour/image-studio-light@1x.avif 1x, /images/tour/image-studio-light@2x.avif 2x');
    expect(img.getAttribute('width')).toBe('640');
    expect(img.getAttribute('height')).toBe('400');
    expect(img.getAttribute('alt')).toBe('');
  });

  it('shows the dark theme’s captures in the dark theme', async () => {
    await create(captures('image-studio'));

    resolvedTheme.set('dark');
    fixture.detectChanges();

    expect(shown()).toEqual(['/images/tour/image-studio-dark@1x.webp']);
  });

  it('selects the panel the address names, and takes focus to its tab', async () => {
    await create(everyPanel);

    await arriveAt('brand-guide');

    expect(selectedTab().textContent?.trim()).toBe('Brand guide');
    expect(document.activeElement).toBe(tabFor('brand-guide'));
  });

  it('follows a second click on a link it has already followed, which changes no address', async () => {
    await create(everyPanel);
    const link = document.createElement('a');
    link.href = '#tour-publishing';
    // The tour's own listener still sees the click; this only stops the runner's address from following it.
    link.addEventListener('click', (event) => event.preventDefault());
    document.body.append(link);

    try {
      // The visitor arrives from the link, tabs away, then clicks the same link again: no hash change this time.
      await arriveAt('publishing');
      host.querySelector<HTMLButtonElement>('#tab-image-studio')!.click();
      fixture.detectChanges();
      expect(selectedTab().textContent?.trim()).toBe('Image Studio');

      link.click();
      fixture.detectChanges();

      expect(selectedTab().textContent?.trim()).toBe('Publishing');
    } finally {
      link.remove();
    }
  });

  it('ignores an address that names no panel of its own', async () => {
    await create(everyPanel);
    const before = selectedTab().textContent?.trim();

    await arriveAt('not-a-panel');

    expect(selectedTab().textContent?.trim()).toBe(before);
  });

  it('hides the frame from assistive technology, which reads the promise and the bullets instead', async () => {
    await create(everyPanel);

    expect(host.querySelector('.frame')?.getAttribute('aria-hidden')).toBe('true');
  });

  it('names every value-prop tour panel, so no card links to a panel the tour lacks', () => {
    DEFAULT_VALUE_PROPS.flatMap((prop) => (prop.tourPanel ? [prop.tourPanel] : [])).forEach((panel) =>
      expect(TOUR_STOPS.map((stop) => stop.panel)).toContain(panel),
    );
  });

  it('gives every stop a promise and exactly three benefits', () => {
    TOUR_STOPS.forEach((stop) => {
      expect(stop.promise.length).toBeGreaterThan(0);
      expect(stop.benefits.length).toBe(3);
    });
  });

  it('carries the publishing panel the same availability words as its card, not a tone alone', async () => {
    await create(captures('publishing'));
    const publishing = TOUR_STOPS.find((stop) => stop.panel === 'publishing')!;

    expect(publishing.badgeLabel).toBe(COMING_TO_EVERY_ACCOUNT);
    expect(host.querySelector('cp-badge')?.textContent).toContain(COMING_TO_EVERY_ACCOUNT);
  });

  it('links every generated capture to a panel the tour knows', () => {
    const known = TOUR_STOPS.map((stop) => stop.panel);

    expect(TOUR_CAPTURES.filter((capture) => !known.includes(capture.panel))).toEqual([]);
  });
});
